    [19323]={name="The Unstoppable Force",quality=4,ilvl=65,reqLevel=60,sourceType="vendor",instructions="Bought from Gaelden Hammersmith.",zone="Alterac Valley",npc="Gaelden Hammersmith",proc="Equip: Improves your chance to get a critical strike by 2.0%."},
    [19335]={name="Spineshatter",quality=4,ilvl=73,reqLevel=60,sourceType="boss_drop",instructions="Drops from Razorgore the Untamed.",zone="Blackwing Lair",npc="Razorgore the Untamed",lore="Set to guard the stolen dragon eggs. The raid takes control of the orb he is chained to and turns him on the clutch he was protecting."},
    [19357]={name="Herald of Woe",quality=4,ilvl=75,reqLevel=60,sourceType="boss_drop",instructions="Drops from Flamegor.",zone="Blackwing Lair",npc="Flamegor",lore="The last of Nefarian's three drakes, and the one that simply gets angrier as the fight goes on."},
    [19358]={name="Draconic Maul",quality=4,ilvl=70,reqLevel=60,sourceType="boss_drop",instructions="Drops from Death Talon Captain.",zone="Blackwing Lair",npc="Death Talon Captain"},
    [19361]={name="Ashjre'thul, Crossbow of Smiting",quality=4,ilvl=77,reqLevel=60,sourceType="boss_drop",instructions="Drops from Chromaggus.",zone="Blackwing Lair",npc="Chromaggus",lore="Nefarian's best result: a two-headed chromatic horror carrying the breath of every dragonflight at once."},
    [19364]={name="Ashkandi, Greatsword of the Brotherhood",quality=4,ilvl=81,reqLevel=60,sourceType="boss_drop",instructions="Drops from Nefarian.",npc="Nefarian",lore="Ashkandi belonged to the Brotherhood of the Light -- the order that kept fighting the Scourge after the Silver Hand broke apart."},
    [19365]={name="Claw of the Black Drake",quality=4,ilvl=75,reqLevel=60,sourceType="boss_drop",instructions="Drops from Firemaw.",zone="Blackwing Lair",npc="Firemaw",lore="One of Nefarian's three guardian drakes, holding the suspended walkways above the lair floor."},
    [19368]={name="Dragonbreath Hand Cannon",quality=4,ilvl=75,reqLevel=60,sourceType="boss_drop",instructions="Drops from Ebonroc.",zone="Blackwing Lair",npc="Ebonroc",lore="One of three drakes guarding Nefarian's inner lair, and the one that heals itself off the wounds it deals."},
    [19372]={name="Helm of Endless Rage",quality=4,ilvl=74,reqLevel=60,sourceType="boss_drop",instructions="Drops from Vaelastrasz the Corrupt.",zone="Blackwing Lair",npc="Vaelastrasz the Corrupt",lore="A red dragon of Alexstrasza's flight, broken by Nefarian's experiments. He asks to be killed before the corruption finishes taking him, and apologises while he fights."},
    [19376]={name="Archimtiros' Ring of Reckoning",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Nefarian.",npc="Nefarian",lore="Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five. He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."},
    [19383]={name="Master Dragonslayer's Medallion",quality=4,ilvl=83,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Lord of Blackrock'. Pick it over the other reward choices. Starts with Highlord Bolvar Fordragon in Stormwind City. Objective: Venture to the Valley of Heroes in Stormwind City and speak with Field Marshal Afrasiabi.",zone="Stormwind City",questName="The Lord of Blackrock"},
    [19384]={name="Master Dragonslayer's Ring",quality=4,ilvl=83,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Lord of Blackrock'. Pick it over the other reward choices. Starts with Highlord Bolvar Fordragon in Stormwind City. Objective: Venture to the Valley of Heroes in Stormwind City and speak with Field Marshal Afrasiabi.",zone="Stormwind City",questName="The Lord of Blackrock",proc="Equip: Improves your chance to hit by 1.0%."},
    [19392]={name="Girdle of the Fallen Crusader",quality=4,ilvl=77,reqLevel=60,sourceType="boss_drop",instructions="Drops from Chromaggus.",zone="Blackwing Lair",npc="Chromaggus",lore="Nefarian's best result: a two-headed chromatic horror carrying the breath of every dragonflight at once."},
    [19402]={name="Legguards of the Fallen Crusader",quality=4,ilvl=75,reqLevel=60,sourceType="boss_drop",instructions="Drops from Firemaw.",zone="Blackwing Lair",npc="Firemaw",lore="One of Nefarian's three guardian drakes, holding the suspended walkways above the lair floor."},
    [19406]={name="Drake Fang Talisman",quality=4,ilvl=75,reqLevel=60,sourceType="boss_drop",instructions="Drops from Ebonroc.",zone="Blackwing Lair",npc="Ebonroc",lore="Cut from the fang of one of Nefarian's drakes. Tanks wore it for the stun it shrugs off, not the numbers on it.",proc="Equip: Increases your chance to Dodge an attack by 1.0%."},
    [19431]={name="Styleen's Impeding Scarab",quality=4,ilvl=75,reqLevel=60,sourceType="boss_drop",instructions="Drops from Flamegor.",zone="Blackwing Lair",npc="Flamegor",lore="The last of Nefarian's three drakes, and the one that simply gets angrier as the fight goes on.",proc="Equip: Increases your chance to Block attacks with a shield by 5.0%."},
    [19432]={name="Circle of Applied Force",quality=4,ilvl=75,reqLevel=60,sourceType="boss_drop",instructions="Drops from Flamegor.",zone="Blackwing Lair",npc="Flamegor",lore="The last of Nefarian's three drakes, and the one that simply gets angrier as the fight goes on."},
    [19491]={name="Amulet of the Darkmoon",quality=4,ilvl=65,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest '1200 Tickets - Amulet of the Darkmoon'. Starts with Gelvas Grimegate in Mulgore. Objective: ProgressStep right up, step right up! &nbsp;If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so! &nbsp;You can redeem tickets in various denominations for wondrous and fantastic prizes. &nbsp;Don't be shy, give it a try!",zone="Mulgore",questName="1200 Tickets - Amulet of the Darkmoon"},
