    [21598]={name="Royal Qiraji Belt",quality=4,ilvl=81,reqLevel=60,sourceType="boss_drop",instructions="Drops from Emperor Vek'lor.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'lor",lore="Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength. Neither twin can be killed far from the other.",proc="Equip: Increases your chance to Parry an attack by 1.0%."},
    [21601]={name="Ring of Emperor Vek'lor",quality=4,ilvl=81,reqLevel=60,sourceType="boss_drop",instructions="Drops from Emperor Vek'lor.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'lor",lore="Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength. Neither twin can be killed far from the other."},
    [21602]={name="Qiraji Execution Bracers",quality=4,ilvl=81,reqLevel=60,sourceType="boss_drop",instructions="Drops from Emperor Vek'lor.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'lor",lore="Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength. Neither twin can be killed far from the other.",proc="Equip: Improves your chance to hit by 1.0%."},
    [21618]={name="Hive Defiler Wristguards",quality=4,ilvl=78,reqLevel=60,sourceType="boss_drop",instructions="Drops from Princess Huhuran.",zone="Temple of Ahn'Qiraj",npc="Princess Huhuran",lore="A qiraji brood matron whose poison is potent enough that the fight is really a race against her venom."},
    [21650]={name="Ancient Qiraji Ripper",quality=4,ilvl=77,reqLevel=60,sourceType="boss_drop",instructions="Drops from Fankriss the Unyielding.",zone="Temple of Ahn'Qiraj",npc="Fankriss the Unyielding",lore="A vast qiraji burrower that spawns its young mid-fight and hurls intruders into the walls.",proc="Equip: Improves your chance to get a critical strike by 1.0%."},
