    [22954]={name="Kiss of the Spider",quality=4,ilvl=85,reqLevel=60,sourceType="boss_drop",instructions="Drops from Maexxna.",zone="Naxxramas",npc="Maexxna",lore="A giant spider webbed into the depths of the Arachnid Quarter, fed on whatever the Scourge no longer needs.",proc="Equip: Improves your chance to hit by 1.0%."},
    [22981]={name="Gluth's Missing Collar",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Gluth.",zone="Naxxramas",npc="Gluth",lore="A stitched hound kept half-starved on purpose, so it would eat anything the Construct Quarter sent its way.",proc="Equip: Increases your chance to Block attacks with a shield by 3.0%."},
    [23001]={name="Eye of Diminution",quality=4,ilvl=85,reqLevel=60,sourceType="boss_drop",instructions="Drops from Thaddius.",zone="Naxxramas",npc="Thaddius",lore="Two abominations sewn into one and animated with stolen lightning -- one of Kel'Thuzad's more ambitious experiments in the Construct Quarter.",proc="Equip: Improves your chance to get a critical strike by 2.0%."},
    [23018]={name="Signet of the Fallen Defender",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Instructor Razuvious.",zone="Naxxramas",npc="Instructor Razuvious",lore="A death knight who trains the Scourge's new officers. He is too strong for his own students to touch, which is exactly the point of the lesson.",proc="Equip: Improves your chance to hit by 1.0%."},
    [23019]={name="Icebane Helmet",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Heigan the Unclean.",zone="Naxxramas",npc="Heigan the Unclean",lore="Keeper of Naxxramas's plague works, and of the corridor of eruptions that has killed more raiders than he has."},
    [23023]={name="Sadist's Collar",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Gothik the Harvester.",zone="Naxxramas",npc="Gothik the Harvester",lore="Razuvious's colleague in the Military Quarter, who fights from behind his own dead and keeps sending them forward.",proc="Equip: Improves your chance to get a critical strike by 1.0%."},
